item.aggregated_output:
        raw = "99"
    return _normalize_exit_code(raw, context)


def _classify_cursor_response(path: str) -> bool:
    try:
        with Path(path).open(encoding="utf-8", errors="replace") as handle:
            for line in handle:
                stripped = line.strip()
                if stripped:
                    return stripped in {_STATUS_CURSOR_EMPTY, _STATUS_CURSOR_DEGRADED}
    except OSError:
        return False
    return False


def _retry_output_path(output: str, suffix: str = "retry") -> str:
    base = output.removesuffix(".txt")
    return f"{base}-{suffix}.txt"


def first_pass_sidecar_path(output: str) -> str:
    if output.endswith(".txt"):
        return f"{output[:-4]}-first-pass.txt"
    return f"{output}-first-pass"


def preserve_and_publish_ns_retry(orig_output: str, retry_output: str, retry_label: str) -> bool:
    first_pass = first_pass_sidecar_path(orig_output)
    try:
        _ = shutil.copyfile(orig_output, first_pass)
        _diagnostic(f"ns-retry: first-pass content preserved at {Path(first_pass).name}")
    except OSError:
        _diagnostic(
            f"collect-results: {retry_label}: failed to preserve first-pass content at {first_pass}; "
            "leaving STATUS=NOT_SUBSTANTIVE"
        )
        return False
    orig_path = Path(orig_output)
    publish_tmp = ""
    try:
        fd, publish_tmp = tempfile.mkstemp(prefix=f".{orig_path.name}.ns-retry.", dir=str(orig_path.parent))
        os.close(fd)
        _ = shutil.copyfile(retry_output, publish_tmp)
        _ = Path(publish_tmp).replace(orig_path)
        _diagnostic(
            f"ns-retry: published retry content to {orig_path.name}; "
            f"retry artifact retained at {Path(retry_output).name}"
        )
        return True
    except OSError:
        for path in (publish_tmp, first_pass):
            if path:
                with contextlib.suppress(FileNotFoundError):
                    Path(path).unlink()
        _diagnostic(
            f"collect-results: {retry_label}: failed to publish retry output to {orig_output}; "
            "leaving STATUS=NOT_SUBSTANTIVE"
        )
        return False


def derive_ns_retry_reason(val_exit: int, ns_mode: str) -> str:
    if ns_mode == "structured":
        return "JSON_PARSE_FAIL" if val_exit == _EXIT_VALIDATION_CURSOR_EMPTY else "UNKNOWN"
    if val_exit in {2, 3}:
        return "NO_ISSUES_FOUND_TOO_THIN"
    if val_exit == _EXIT_OUTPUT_EMPTY:
        return "OUTPUT_EMPTY"
    return "UNKNOWN"


def _validate_retry_timeout(meta: RetryMeta) -> tuple[int | None, str]:
    if not meta.timeout:
        return None, "Retry metadata invalid: TIMEOUT missing"
    if not re.fullmatch(r"[0-9]+", meta.timeout) or int(meta.timeout, 10) < 1:
        return None, "Retry metadata invalid: TIMEOUT not a positive integer"
    return int(meta.timeout, 10), ""


def _mark_retry_metadata_invalid(records: list[CollectorRecord], idx: int, orig_output: str, reason: str) -> None:
    records[idx] = CollectorRecord(
        reviewer_file=orig_output,
        tool=derive_tool(orig_output),
        status="EMPTY_OUTPUT",
        exit_code="99",
        failure_reason=reason,
    )


def _cmd_has_token(cmd: Sequence[str], needle: str) -> bool:
    return needle in cmd


def _cmd_json_shape_valid_for_tool(tool: str, cmd: Sequence[str]) -> tuple[bool, str]:
    if not cmd:
        return False, "rejected"
    argv0 = Path(cmd[0]).name
    if tool == "cursor":
        if len(cmd) < _MIN_TOOL_ARGC or argv0 != "cursor" or cmd[1] != "agent":
            return False, "rejected"
        if not _cmd_has_token(cmd, "--workspace") or _cmd_has_token(cmd, "--add-dir"):
            return False, "rejected"
        return True, ""
    if tool == "codex":
        if len(cmd) < _MIN_TOOL_ARGC or argv0 != "codex" or cmd[1] != "exec":
            return False, "rejected"
        for token in ("-C", "--add-dir", "--output-last-message"):
            if not _cmd_has_token(cmd, token):
                return False, "rejected"
        return True, ""
    return False, "unknown"


def _cmd_json_requires_outer_launcher(orig_output: str, tool: str, cmd: Sequence[str]) -> bool:
    if Path(f"{orig_output}.prompt").is_file():
        return True
    if len(cmd) < _MIN_TOOL_ARGC:
        return False
    argv0 = Path(cmd[0]).name
    if tool == "cursor" and argv0 == "cursor" and cmd[1] == "agent":
        mode = ""
        for idx, arg in enumerate(cmd[:-1]):
            if arg == "--mode":
                mode = cmd[idx + 1]
        return mode == "ask"
    if tool == "codex" and argv0 == "codex" and cmd[1] == "exec":
        sandbox = ""
        for idx, arg in enumerate(cmd[:-1]):
            if arg == "--sandbox":
                sandbox = cmd[idx + 1]
        return sandbox == "read-only"
    return False


def _env_without_test_hooks() -> dict[str, str]:
    env = dict(os.environ)
    for key in list(env):
        if key.startswith("LARCH_COLLECT_RESULTS_"):
            _ = env.pop(key, None)
    for key in (
        "LARCH_ALLOW_TEST_HOOKS",
        "LARCH_TEST_TRAP_AFTER_INNER_DONE_FILE",
        "LARCH_TEST_TRAP_AFTER_INNER_DONE",
        "RUN_EXTERNAL_AGENT_INNER_SENTINEL_SUFFIX",
    ):
        _ = env.pop(key, None)
    return env


def _safe_meta_path_value(value: str) -> bool:
    return ".." not in value


def _parse_json_string_array(raw: str) -> tuple[list[str] | None, str]:
    try:
        obj = json.loads(raw)
    except json.JSONDecodeError:
        return None, "malformed CMD_JSON"
    if not isinstance(obj, list) or not obj:
        return None, "malformed CMD_JSON"
    items: list[str] = []
    for item in obj:
        if not isinstance(item, str):
            return None, "malformed CMD_JSON"
        items.append(item)
    return items, ""


def _launch_cmd_json_retry(
    plan: RetryPlan,
    meta: RetryMeta,
    records: list[CollectorRecord],
    *,
    strong_prompt: bool = False,
) -> bool:
    if not meta.cmd_json and not meta.tool:
        _mark_retry_metadata_invalid(records, plan.index, plan.orig_output, "Retry metadata invalid: missing CMD_JSON and TOOL")
        return False
    if not meta.cmd_json:
        _mark_retry_metadata_invalid(records, plan.index, plan.orig_output, "Retry metadata invalid: missing CMD_JSON")
        return False
    if not meta.tool:
        _mark_retry_metadata_invalid(records, plan.index, plan.orig_output, "Retry metadata invalid: missing TOOL")
        return False
    cmd, err = _parse_json_string_array(meta.cmd_json)
    if cmd is None:
        _mark_retry_metadata_invalid(records, plan.index, plan.orig_output, f"Retry metadata invalid: {err}")
        return False
    if meta.orig_output:
        cmd = [plan.retry_output if item == meta.orig_output else item for item in cmd]
    ok, shape_reason = _cmd_json_shape_valid_for_tool(meta.tool, cmd)
    if not ok:
        reason = "unknown TOOL for CMD_JSON" if shape_reason == "unknown" else f"CMD_JSON argv shape rejected for {meta.tool}"
        _mark_retry_metadata_invalid(records, plan.index, plan.orig_output, f"Retry metadata invalid: {reason}")
        return False
    if _cmd_json_requires_outer_launcher(plan.orig_output, meta.tool, cmd):
        _mark_retry_metadata_invalid(records, plan.index, plan.orig_output, "Retry metadata invalid: review-shaped CMD_JSON requires outer launcher metadata")
        return False
    if meta.stderr_sink and not _safe_meta_path_value(meta.stderr_sink):
        _mark_retry_metadata_invalid(records, plan.index, plan.orig_output, "Retry metadata invalid: STDERR_SINK contains ..")
        return False
    if strong_prompt and cmd:
        cmd[-1] = _COLLECTOR_NS_STRONG_HEADER + cmd[-1]
    args = [
        sys.executable,
        str(PY_CLI),
        "agent",
        "run-external-agent",
        "--tool",
        meta.tool,
        "--output",
        plan.retry_output,
        "--timeout",
        str(plan.timeout),
    ]
    if meta.capture_stdout == "true":
        args.append("--capture-stdout")
    elif meta.capture_stdout_only == "true":
        args.append("--capture-stdout-only")
    if meta.stderr_sink:
        args.extend(["--stderr-sink", meta.stderr_sink])
    args.append("--")
    args.extend(cmd)
    plan.process = subprocess.Popen(  # pylint: disable=consider-using-with
        args,
        env=_env_without_test_hooks(),
        stdout=subprocess.DEVNULL,
        stderr=subprocess.DEVNULL,
    )
    plan.sentinel = f"{plan.retry_output}.done"
    plan.launched = True
    return True


def _build_codex_exec_retry_args(plan: RetryPlan, meta: RetryMeta, records: list[CollectorRecord], prompt_file: str) -> list[str] | None:
    if meta.outer_launcher_kind != "codex-exec":
        _mark_retry_metadata_invalid(records, plan.index, plan.orig_output, "Retry metadata invalid: OUTER_LAUNCHER_KIND must be codex-exec")
        return None
    if meta.outer_launcher_sandbox not in {"full-auto", "read-only"}:
        _mark_retry_metadata_invalid(records, plan.index, plan.orig_output, "Retry metadata invalid: OUTER_LAUNCHER_SANDBOX invalid")
        return None
    if meta.outer_launcher_with_effort not in {"true", "false"}:
        _mark_retry_metadata_invalid(records, plan.index, plan.orig_output, "Retry metadata invalid: OUTER_LAUNCHER_WITH_EFFORT invalid")
        return None
    if not meta.outer_launcher_usage_label:
        _mark_retry_metadata_invalid(records, plan.index, plan.orig_output, "Retry metadata invalid: missing OUTER_LAUNCHER_USAGE_LABEL")
        return None
    if not meta.outer_launcher_timing_kind:
        _mark_retry_metadata_invalid(records, plan.index, plan.orig_output, "Retry metadata invalid: missing OUTER_LAUNCHER_TIMING_KIND")
        return None
    try:
        add_dirs_obj = json.loads(meta.outer_launcher_add_dirs_json or "[]")
    except json.JSONDecodeError:
        _mark_retry_metadata_invalid(records, plan.index, plan.orig_output, "Retry metadata invalid: OUTER_LAUNCHER_ADD_DIRS_JSON malformed")
        return None
    if not isinstance(add_dirs_obj, list):
        _mark_retry_metadata_invalid(records, plan.index, plan.orig_output, "Retry metadata invalid: OUTER_LAUNCHER_ADD_DIRS_JSON malformed")
        return None
    add_dirs: list[str] = []
    for item in add_dirs_obj:
        if not isinstance(item, str):
            _mark_retry_metadata_invalid(records, plan.index, plan.orig_output, "Retry metadata invalid: OUTER_LAUNCHER_ADD_DIRS_JSON malformed")
            return None
        add_dirs.append(item)
    args = [
        "--output",
        plan.retry_output,
        "--timeout",
        str(plan.timeout),
        "--workdir",
        meta.outer_launcher_workdir,
        "--prompt-file",
        prompt_file,
        "--sandbox",
        meta.outer_launcher_sandbox,
        "--usage-label",
        meta.outer_launcher_usage_label,
        "--timing-task-kind",
        meta.outer_launcher_timing_kind,
    ]
    if meta.outer_launcher_with_effort == "true":
        args.append("--with-effort")
    for add_dir in add_dirs:
        if add_dir:
            args.extend(["--add-dir", add_dir])
    return args


def _launch_outer_retry(
    plan: RetryPlan,
    meta: RetryMeta,
    records: list[CollectorRecord],
    *,
    prompt_override: str = "",
) -> bool:
    if not meta.outer_launcher:
        _mark_retry_metadata_invalid(records, plan.index, plan.orig_output, "Retry metadata invalid: missing OUTER_LAUNCHER")
        return False
    if not meta.outer_launcher_prompt_file:
        _mark_retry_metadata_invalid(records, plan.index, plan.orig_output, "Retry metadata invalid: missing OUTER_LAUNCHER_PROMPT_FILE")
        return False
    if not meta.outer_launcher_workdir:
        _mark_retry_metadata_invalid(records, plan.index, plan.orig_output, "Retry metadata invalid: missing OUTER_LAUNCHER_WORKDIR")
        return False
    if not _safe_meta_path_value(meta.outer_launcher):
        _mark_retry_metadata_invalid(records, plan.index, plan.orig_output, "Retry metadata invalid: OUTER_LAUNCHER contains ..")
        return False
    if meta.outer_launcher == "agent launch-review":
        launcher_kind = "review"
    elif meta.outer_launcher == "agent launch-codex-exec":
        launcher_kind = "codex-exec"
    elif meta.outer_launcher.endswith("/launch-review.sh") or meta.outer_launcher == "launch-review.sh":
        _mark_retry_metadata_invalid(records, plan.index, plan.orig_output, "Retry metadata invalid: retired review OUTER_LAUNCHER metadata is no longer accepted")
        return False
    else:
        _mark_retry_metadata_invalid(records, plan.index, plan.orig_output, "Retry metadata invalid: OUTER_LAUNCHER not canonical agent launch-review or agent launch-codex-exec")
        return False
    expected_prompt = f"{plan.orig_output}.prompt"
    if not _safe_meta_path_value(meta.outer_launcher_prompt_file):
        _mark_retry_metadata_invalid(records, plan.index, plan.orig_output, "Retry metadata invalid: OUTER_LAUNCHER_PROMPT_FILE contains ..")
        return False
    if meta.outer_launcher_prompt_file != expected_prompt:
        _mark_retry_metadata_invalid(records, plan.index, plan.orig_output, "Retry metadata invalid: OUTER_LAUNCHER_PROMPT_FILE not the expected sidecar")
        return False
    prompt_for_launch = prompt_override or meta.outer_launcher_prompt_file
    prompt_path = Path(prompt_for_launch)
    if not prompt_path.is_file() or prompt_path.is_symlink():
        _mark_retry_metadata_invalid(records, plan.index, plan.orig_output, "Retry metadata invalid: OUTER_LAUNCHER_PROMPT_FILE not a readable regular non-symlink file")
        return False
    if not _safe_meta_path_value(meta.outer_launcher_workdir):
        _mark_retry_metadata_invalid(records, plan.index, plan.orig_output, "Retry metadata invalid: OUTER_LAUNCHER_WORKDIR contains ..")
        return False
    if not Path(meta.outer_launcher_workdir).is_dir():
        _mark_retry_metadata_invalid(records, plan.index, plan.orig_output, "Retry metadata invalid: OUTER_LAUNCHER_WORKDIR not a directory")
        return False
    if launcher_kind == "review":
        risk = meta.outer_launcher_risk if meta.outer_launcher_risk in {"high", "low"} else "high"
        if meta.stderr_sink and not _safe_meta_path_value(meta.stderr_sink):
            _mark_retry_metadata_invalid(records, plan.index, plan.orig_output, "Retry metadata invalid: STDERR_SINK contains ..")
            return False
        timing_kind = meta.outer_launcher_timing_kind
        if not timing_kind:
            if meta.tool == "codex":
                timing_kind = os.environ.get("LARCH_TIMING_TASK_KIND", "codex-review")
            elif meta.tool == "cursor":
                timing_kind = os.environ.get("LARCH_TIMING_TASK_KIND", "cursor-review")
        args = [
            sys.executable,
            str(PY_CLI),
            "agent",
            "launch-review",
            "--tool",
            meta.tool,
            "--output",
            plan.retry_output,
            "--timeout",
            str(plan.timeout),
            "--risk",
            risk,
            "--timing-task-kind",
            timing_kind,
            "--prompt-file",
            prompt_for_launch,
        ]
        if meta.stderr_sink:
            args.extend(["--stderr-sink", meta.stderr_sink])
    else:
        extra = _build_codex_exec_retry_args(plan, meta, records, prompt_for_launch)
        if extra is None:
            return False
        args = [sys.executable, str(PY_CLI), "agent", "launch-codex-exec", *extra]
    plan.process = subprocess.Popen(  # pylint: disable=consider-using-with
        args,
        cwd=meta.outer_launcher_workdir,
        env=_env_without_test_hooks(),
        stdout=subprocess.DEVNULL,
        stderr=subprocess.DEVNULL,
    )
    plan.sentinel = f"{plan.retry_output}.done"
    plan.launched = True
    return True


def _launch_retry_plan(plan: RetryPlan, records: list[CollectorRecord], *, strong_prompt: bool = False) -> bool:
    meta = _parse_meta(f"{plan.orig_output}.meta")
    timeout, reason = _validate_retry_timeout(meta)
    if timeout is None:
        _mark_retry_metadata_invalid(records, plan.index, plan.orig_output, reason)
        return False
    plan.timeout = timeout
    if meta.outer_launcher or meta.outer_launcher_prompt_file or meta.outer_launcher_workdir:
        prompt_override = ""
        if strong_prompt:
            fd, temp_prompt = tempfile.mkstemp(prefix="larch-ns-retry-prompt.", dir=os.environ.get("TMPDIR") or None)
            os.close(fd)
            try:
                original = Path(meta.outer_launcher_prompt_file).read_text(encoding="utf-8", errors="replace")
                _ = Path(temp_prompt).write_text(_COLLECTOR_NS_STRONG_HEADER + original, encoding="utf-8")
            except OSError:
                with contextlib.suppress(FileNotFoundError):
                    Path(temp_prompt).unlink()
                return False
            plan.temp_prompt = temp_prompt
            prompt_override = temp_prompt
        ok = _launch_outer_retry(plan, meta, records, prompt_override=prompt_override)
        if not ok and plan.temp_prompt:
            with contextlib.suppress(FileNotFoundError):
                Path(plan.temp_prompt).unlink()
            plan.temp_prompt = ""
        return ok
    return _launch_cmd_json_retry(plan, meta, records, strong_prompt=strong_prompt)


def _wait_retry_plans(plans: Sequence[RetryPlan]) -> None:
    sentinels = [plan.sentinel for plan in plans if plan.launched and plan.sentinel]
    if not sentinels:
        return
    timeout = _RETRY_WAIT_FLOOR
    for plan in plans:
        if plan.launched:
            timeout = max(timeout, plan.timeout + _RETRY_WAIT_GRACE)
    _ = review_dispatch.wait_reviewers(
        sentinels,
        timeout=timeout,
        emit_fn=lambda _line: None,
        diagnostic_fn=lambda _line: None,
    )
    for plan in plans:
        proc = plan.process
        if proc is not None:
            with contextlib.suppress(Exception):
                _ = proc.wait(timeout=0)


def _retry_failure_result(records: list[CollectorRecord], plan: RetryPlan) -> None:
    tool = derive_tool(plan.orig_output)
    sentinel = Path(plan.sentinel)
    if sentinel.is_file():
        retry_exit, _ = _read_sentinel_exit(str(sentinel), "retry sentinel")
        if retry_exit == _TIMEOUT_EXIT:
            retry_status = "TIMED_OUT"
        elif retry_exit != "0":
            retry_status = "FAILED"
        else:
            retry_status = "EMPTY_OUTPUT"
        retry_reason = build_failure_reason(plan.retry_output, retry_status, retry_exit)
        records[plan.index] = CollectorRecord(
            reviewer_file=plan.orig_output,
            tool=tool,
            status="EMPTY_OUTPUT",
            exit_code=retry_exit,
            failure_reason=f"Retry also failed: {retry_reason}",
        )
    else:
        records[plan.index] = CollectorRecord(
            reviewer_file=plan.orig_output,
            tool=tool,
            status="EMPTY_OUTPUT",
            exit_code="99",
            structured_sidecar="",
            failure_reason="Retry process did not complete (sentinel file missing)",
        )


def _apply_empty_retry_results(records: list[CollectorRecord], plans: Sequence[RetryPlan]) -> None:
    for plan in plans:
        if not plan.launched:
            continue
        tool = derive_tool(plan.orig_output)
        sentinel = Path(plan.sentinel)
        output = Path(plan.retry_output)
        if sentinel.is_file():
            retry_exit, _ = _read_sentinel_exit(str(sentinel), "retry sentinel")
            if retry_exit == "0" and output.is_file() and output.stat().st_size > 0:
                if _classify_cursor_response(plan.retry_output):
                    records[plan.index] = CollectorRecord(
                        reviewer_file=plan.retry_output,
                        tool=tool,
                        status=_STATUS_CURSOR_EMPTY,
                        exit_code="0",
                        failure_reason="cursor narration-only / degraded backend response (retry)",
                    )
                else:
                    records[plan.index] = CollectorRecord(plan.retry_output, tool, "OK", "0")
                for tail in (f"{plan.orig_output}.stderr-tail", f"{plan.retry_output}.stderr-tail"):
                    with contextlib.suppress(FileNotFoundError):
                        Path(tail).unlink()
            else:
                _retry_failure_result(records, plan)
        else:
            _retry_failure_result(records, plan)


def _run_validator(args: Sequence[str]) -> CommandResult:
    proc = subprocess.run(
        [sys.executable, str(PY_CLI), "eval", "validate-research-output", *args],
        text=True,
        capture_output=True,
        check=False,
    )
    return CommandResult(proc.returncode, proc.stdout, proc.stderr)


def _validate_substantive(records: list[CollectorRecord], *, validation_mode: bool) -> None:
    val_args = ["--validation-mode"] if validation_mode else []
    for idx, record in enumerate(list(records)):
        if record.status != "OK":
            continue
        result = _run_validator([*val_args, record.reviewer_file])
        if result.returncode == 0:
            continue
        diag = _sanitize_failure_reason(result.stdout + result.stderr, limit=_VALIDATION_REASON_LIMIT)
        if result.returncode == _EXIT_VALIDATION_CURSOR_EMPTY:
            records[idx] = CollectorRecord(record.reviewer_file, record.tool, _STATUS_CURSOR_EMPTY, "0", failure_reason=diag)
        else:
            records[idx] = CollectorRecord(
                record.reviewer_file,
                record.tool,
                "NOT_SUBSTANTIVE",
                "0",
                failure_reason=diag,
                ns_retry_mode="substantive",
                ns_retry_reason=derive_ns_retry_reason(result.returncode, "substantive"),
            )


def _structured_sidecar_path(record: CollectorRecord) -> str:
    suffix = ".tsv" if record.tool in {"cursor", "codex"} else ".jsonl"
    return f"{record.reviewer_file}{suffix}"


def _validate_structured(records: list[CollectorRecord]) -> None:
    for idx, record in enumerate(list(records)):
        if record.status != "OK":
            record.structured_sidecar = record.structured_sidecar or ""
            continue
        sidecar = _structured_sidecar_path(record)
        result = _run_validator(["--structured-reviewer-mode", "--write-structured", sidecar, record.reviewer_file])
        if result.returncode == 0:
            record.structured_sidecar = sidecar
            records[idx] = record
        else:
            diag = _sanitize_failure_reason(result.stdout + result.stderr, limit=_VALIDATION_REASON_LIMIT)
            records[idx] = CollectorRecord(
                record.reviewer_file,
                record.tool,
                "NOT_SUBSTANTIVE",
                "0",
                structured_sidecar="",
                failure_reason=diag,
                ns_retry_mode="structured",
                ns_retry_reason=derive_ns_retry_reason(result.returncode, "structured"),
            )


def _collect_ns_retry_plans(records: list[CollectorRecord]) -> list[RetryPlan]:
    plans: list[RetryPlan] = []
    for idx, record in enumerate(records):
        if record.status != "NOT_SUBSTANTIVE" or not record.ns_retry_mode:
            continue
        if not Path(f"{record.reviewer_file}.meta").is_file():
            continue
        meta = _parse_meta(f"{record.reviewer_file}.meta")
        timeout, reason = _validate_retry_timeout(meta)
        if timeout is None:
            _mark_retry_metadata_invalid(records, idx, record.reviewer_file, reason)
            continue
        plans.append(
            RetryPlan(
                index=idx,
                orig_output=record.reviewer_file,
                retry_output=_retry_output_path(record.reviewer_file, "ns-retry"),
                timeout=timeout,
                mode=record.ns_retry_mode,
                ns_retry_reason=record.ns_retry_reason or "UNKNOWN",
            )
        )
    return plans


def _apply_ns_retry_results(records: list[CollectorRecord], plans: Sequence[RetryPlan], *, validation_mode: bool) -> None:
    val_args = ["--validation-mode"] if validation_mode else []
    for plan in plans:
        if not plan.launched:
            continue
        retry_meta = Path(f"{plan.retry_output}.meta")
        if retry_meta.is_file() and not retry_meta.is_symlink():
            with contextlib.suppress(OSError):
                with retry_meta.open("a", encoding="utf-8") as handle:
                    _ = handle.write(f"NS_RETRY_REASON={plan.ns_retry_reason or 'UNKNOWN'}\n")
        retry_sentinel = Path(plan.sentinel)
        retry_file = Path(plan.retry_output)
        if not (retry_sentinel.is_file() and retry_file.is_file() and retry_file.stat().st_size > 0):
            continue
        ns_exit, _ = _read_sentinel_exit(str(retry_sentinel), "ns-retry sentinel")
        if ns_exit != "0":
            continue
        entry_tool = records[plan.index].tool
        if plan.mode == "structured":
            sidecar = f"{plan.retry_output}{'.tsv' if entry_tool in {'cursor', 'codex'} else '.jsonl'}"
            result = _run_validator(["--structured-reviewer-mode", "--write-structured", sidecar, plan.retry_output])
            if result.returncode != 0 or not Path(sidecar).is_file():
                continue
            if not preserve_and_publish_ns_retry(plan.orig_output, plan.retry_output, "structured NS retry"):
                continue
            final_sidecar = f"{plan.orig_output}.{Path(sidecar).suffix.lstrip('.')}"
            with contextlib.suppress(OSError):
                _ = shutil.copyfile(sidecar, final_sidecar)
                sidecar = final_sidecar
            if _classify_cursor_response(plan.orig_output):
                records[plan.index] = CollectorRecord(plan.orig_output, entry_tool, _STATUS_CURSOR_EMPTY, "0", failure_reason="cursor narration-only / degraded backend response (structured ns-retry)")
            else:
                records[plan.index] = CollectorRecord(plan.orig_output, entry_tool, "OK", "0", structured_sidecar=sidecar)
        else:
            result = _run_validator([*val_args, plan.retry_output])
            if result.returncode != 0:
                continue
            if not preserve_and_publish_ns_retry(plan.orig_output, plan.retry_output, "substantive NS retry"):
                continue
            if _classify_cursor_response(plan.orig_output):
                records[plan.index] = CollectorRecord(plan.orig_output, entry_tool, _STATUS_CURSOR_EMPTY, "0", failure_reason="cursor narration-only / degraded backend response (substantive ns-retry)")
            else:
                records[plan.index] = CollectorRecord(plan.orig_output, entry_tool, "OK", "0")
        for tail in (f"{plan.orig_output}.stderr-tail", f"{plan.retry_output}.stderr-tail"):
            with contextlib.suppress(FileNotFoundError):
                Path(tail).unlink()
    for plan in plans:
        if plan.temp_prompt:
            with contextlib.suppress(FileNotFoundError):
                Path(plan.temp_prompt).unlink()


def collector_stderr_tail_candidates(reviewer_file: str) -> list[str]:
    candidates = [reviewer_file]
    if reviewer_file.endswith("-phase3.txt"):
        candidates.append(f"{reviewer_file[:-11]}-phase2.txt")
        candidates.append(f"{reviewer_file[:-11]}.txt")
    elif reviewer_file.endswith(("-phase2.txt", "-phase1.txt")):
        candidates.append(f"{reviewer_file[:-11]}.txt")
    return candidates


def resolve_collector_stderr_tail_file(reviewer_file: str) -> str:
    base = reviewer_file.removesuffix(".txt")
    retry_tail = f"{base}-retry.txt.stderr-tail"
    if Path(retry_tail).is_file() and Path(retry_tail).stat().st_size > 0:
        return retry_tail
    ns_retry_tail = f"{base}-ns-retry.txt.stderr-tail"
    if Path(ns_retry_tail).is_file() and Path(ns_retry_tail).stat().st_size > 0:
        return ns_retry_tail
    for candidate in collector_stderr_tail_candidates(reviewer_file):
        launch_stderr = f"{candidate}.launch-stderr"
        if Path(launch_stderr).is_file() and Path(launch_stderr).stat().st_size > 0:
            fd, tmp_tail = tempfile.mkstemp(prefix="larch-launch-stderr-tail.", dir=os.environ.get("TMPDIR") or None)
            os.close(fd)
            rendered = review_dispatch.render_failed_agent_stderr_tail(launch_stderr)
            if rendered:
                _ = Path(tmp_tail).write_text(rendered, encoding="utf-8")
                return tmp_tail
            with contextlib.suppress(FileNotFoundError):
                Path(tmp_tail).unlink()
        tail = f"{candidate}.stderr-tail"
        if Path(tail).is_file() and Path(tail).stat().st_size > 0:
            return tail
    return ""


def failed_agent_stderr_signature(tail_file: str) -> str:
    text = _read_nonempty(tail_file)
    if not text:
        return ""
    home_cache = str(Path.home() / ".cache" / "larch" / "sessions")
    norm = re.sub(r"0x[0-9a-fA-F]+", "0x#", text)
    norm = re.sub(r"[0-9]+", "#", norm)
    norm = re.sub(r"/tmp\S*", "<path>", norm)  # noqa: S108 - redaction pattern, not a filesystem path
    norm = re.sub(r"/var/folders\S*", "<path>", norm)
    if home_cache:
        norm = re.sub(re.escape(home_cache) + r"\S*", "<path>", norm)
    norm = re.sub(r"\S+\.(txt|stderr-tail|sidecar|diag|done)( |$)", r"<out>\2", norm)
    cksum_bin = shutil.which("cksum")
    cksum_bin = shutil.which("cksum")
    if not cksum_bin:
        return ""
    proc = subprocess.run(
        [cksum_bin],
        input=norm.encode("utf-8"),
        capture_output=True,
        check=False,
    )
    if proc.returncode == 0 and proc.stdout:
        return proc.stdout.decode("utf-8", errors="replace").split()[0]
    return ""


def _emit_failed_agent_stderr_tails(records: Sequence[CollectorRecord]) -> None:
    seen: dict[str, str] = {}
    for record in records:
        if record.status in {"OK", "cap_hit", ""}:
            continue
        tail_file = resolve_collector_stderr_tail_file(record.reviewer_file)
        if not tail_file:
            continue
        sig = failed_agent_stderr_signature(tail_file)
        base = Path(record.reviewer_file).name
        if sig and sig in seen:
            _diagnostic(
                f"↩ {record.tool or 'unknown'} {base}: identical failure to {seen[sig]} "
                f"(root-cause sig {sig}); stderr tail suppressed"
            )
            if "/larch-launch-stderr-tail." in tail_file:
                with contextlib.suppress(FileNotFoundError):
                    Path(tail_file).unlink()
            continue
        if sig:
            seen[sig] = base
        rendered = review_dispatch.render_failed_agent_stderr_tail(tail_file)
        if rendered:
            _diagnostic("--- failed agent stderr tail ---")
            for line in rendered.splitlines():
                if line:
                    _diagnostic(line)
            _diagnostic("--- end failed agent stderr tail ---")
        if "/larch-launch-stderr-tail." in tail_file:
            with contextlib.suppress(FileNotFoundError):
                Path(tail_file).unlink()


def _parse_wait_timeouts(lines: Sequence[str]) -> set[int]:
    timed_out: set[int] = set()
    for line in lines:
        if not line.startswith("TIMEOUT "):
            continue
        parts = line.split(maxsplit=2)
        if len(parts) >= _MIN_WAIT_PARTS and parts[1].isdigit():
            timed_out.add(int(parts[1], 10))
    return timed_out


def _initial_wait(timeout: int, output_files: Sequence[str]) -> tuple[int, set[int]]:
    sentinels = [f"{path}.done" for path in output_files]
    emitted: list[str] = []
    diagnostics: list[str] = []
    rc = review_dispatch.wait_reviewers(
        sentinels,
        timeout=timeout,
        emit_fn=emitted.append,
        diagnostic_fn=diagnostics.append,
    )
    if rc != 0:
        for line in diagnostics:
            if line.strip():
                _diagnostic(line)
        _diagnostic(f"collect-results: wait-reviewers exited {rc}")
        return rc, set()
    return 0, _parse_wait_timeouts(emitted)


def _build_initial_records(options: CollectorOptions, timed_out_indexes: set[int]) -> tuple[list[CollectorRecord], list[RetryPlan]]:
    records: list[CollectorRecord] = []
    retry_plans: list[RetryPlan] = []
    for zero_idx, output in enumerate(options.output_files):
        wait_idx = zero_idx + 1
        sentinel = f"{output}.done"
        meta_path = f"{output}.meta"
        tool = derive_tool(output)
        record = CollectorRecord(output, tool, "OK", "0")
        if wait_idx in timed_out_indexes:
            record.status = "SENTINEL_TIMEOUT"
            record.exit_code = _TIMEOUT_EXIT
            record.failure_reason = build_failure_reason(output, record.status, record.exit_code)
        elif Path(sentinel).is_file():
            exit_code, coerced = _read_sentinel_exit(sentinel, "initial sentinel")
            record.exit_code = exit_code
            output_nonempty = Path(output).is_file() and Path(output).stat().st_size > 0
            if record.exit_code == _TIMEOUT_EXIT:
                record.status = "TIMED_OUT"
                record.failure_reason = build_failure_reason(output, record.status, record.exit_code)
            elif record.exit_code != "0" and not (coerced and not output_nonempty):
                record.status = "FAILED"
                record.failure_reason = build_failure_reason(output, record.status, record.exit_code)
            elif output_nonempty and _read_nonempty(output).splitlines()[0:1] == ["STATUS=cap_hit"]:
                record.status = "cap_hit"
                record.failure_reason = "Token budget cap hit; reviewer skipped"
            elif not output_nonempty:
                record.status = "EMPTY_OUTPUT"
                record.failure_reason = build_failure_reason(output, record.status, record.exit_code)
                if Path(meta_path).is_file():
                    meta = _parse_meta(meta_path)
                    timeout, reason = _validate_retry_timeout(meta)
                    if timeout is None:
                        record = CollectorRecord(output, tool, "EMPTY_OUTPUT", "99", failure_reason=reason)
                    else:
                        retry_plans.append(RetryPlan(zero_idx, output, _retry_output_path(output), timeout))
        else:
            record.status = "SENTINEL_TIMEOUT"
            record.exit_code = _TIMEOUT_EXIT
            record.failure_reason = build_failure_reason(output, record.status, record.exit_code)

        if (
            record.status in {"FAILED", "TIMED_OUT", "SENTINEL_TIMEOUT"}
            and Path(f"{output}.diag").is_file()
            and retry.is_transient_net_signature(record.failure_reason)
            and Path(meta_path).is_file()
        ):
            meta = _parse_meta(meta_path)
            timeout, reason = _validate_retry_timeout(meta)
            if timeout is None:
                record = CollectorRecord(output, tool, "EMPTY_OUTPUT", "99", failure_reason=reason)
            else:
                record.status = "EMPTY_OUTPUT"
                _diagnostic(f"collect-results: transient diagnostic for {Path(output).name}; retrying once")
                retry_plans.append(RetryPlan(zero_idx, output, _retry_output_path(output), timeout))
        if record.status == "OK" and _classify_cursor_response(output):
            record.status = _STATUS_CURSOR_EMPTY
            record.failure_reason = "cursor narration-only / degraded backend response"
        records.append(record)
    return records, retry_plans


def collect_results(options: CollectorOptions) -> int:
    wait_rc, timed_out_indexes = _initial_wait(options.timeout, options.output_files)
    if wait_rc != 0:
        return 1
    records, retry_plans = _build_initial_records(options, timed_out_indexes)
    launched_retry_plans = [plan for plan in retry_plans if _launch_retry_plan(plan, records)]
    _wait_retry_plans(launched_retry_plans)
    _apply_empty_retry_results(records, retry_plans)
    if options.substantive_validation:
        _validate_substantive(records, validation_mode=options.validation_mode)
    if options.structured_reviewer_validation:
        _validate_structured(records)
    if options.substantive_validation or options.structured_reviewer_validation:
        ns_plans = _collect_ns_retry_plans(records)
        launched_ns_plans = [plan for plan in ns_plans if _launch_retry_plan(plan, records, strong_prompt=True)]
        _wait_retry_plans(launched_ns_plans)
        _apply_ns_retry_results(records, ns_plans, validation_mode=options.validation_mode)
    if not options.summary_only:
        _emit_failed_agent_stderr_tails(records)
    _emit_records(records, summary_only=options.summary_only)
    return 0


def _emit_records(records: Sequence[CollectorRecord], *, summary_only: bool) -> None:
    first = True
    for record in records:
        if first:
            first = False
        else:
            _emit("")
        for field in record.fields(summary_only=summary_only):
            _emit(field)


def _paths_from_file(path: str) -> tuple[list[str] | None, str]:
    p = Path(path)
    if not p.exists() or not os.access(p, os.R_OK):
        return None, f"collect-results: paths-file not readable: {path}"
    if not p.is_file():
        return None, f"collect-results: paths-file is not a regular file: {path}"
    try:
        lines = p.read_text(encoding="utf-8", errors="replace").splitlines()
    except OSError:
        return None, f"collect-results: paths-file not readable: {path}"
    outputs = [line for line in lines if line.strip()]
    if not outputs:
        return None, "collect-results: paths-file contains no entries (preserves anti-pattern #4)"
    return outputs, ""


def _usage() -> str:
    return (

"""Progress breadcrumbs and JSONL journal (observability only)."""

from __future__ import annotations

import json
import os
import sys
from contextlib import suppress
from dataclasses import dataclass
from datetime import UTC, datetime
from pathlib import Path
from typing import Any, TextIO

import config
import redact

_self_initialized_quiet = False


def reset_quiet_state() -> None:
    """Reset quiet routing state for tests and subprocess re-entry."""
    global _self_initialized_quiet  # noqa: PLW0603
    _self_initialized_quiet = False
    _clear_quiet_env()


def _env_truthy(name: str) -> bool:
    return os.environ.get(name, "").lower() in {
        "1",
        "true",
        "yes",
        "on",
    }


def _quiet_disabled() -> bool:
    return _env_truthy(config.ENV_LARCH_QUIET_DISABLE)


def _quiet_active() -> bool:
    return (
        _env_truthy(config.ENV_LARCH_QUIET_ACTIVE)
        and bool(os.environ.get(config.ENV_LARCH_QUIET_PID, ""))
        and not _quiet_disabled()
    )


def _clear_quiet_env() -> None:
    _ = os.environ.pop(config.ENV_LARCH_QUIET_ACTIVE, None)
    _ = os.environ.pop(config.ENV_LARCH_QUIET_PID, None)
    _ = os.environ.pop(config.ENV_LARCH_QUIET_LOG_FILE, None)


def quiet_init(*, argv0: str | None = None) -> None:
    """Initialize lib-quiet-style stdout/stderr routing for this process."""
    global _self_initialized_quiet  # noqa: PLW0603
    if _quiet_disabled():
        return
    active_pid = os.environ.get(config.ENV_LARCH_QUIET_PID, "")
    if _env_truthy(config.ENV_LARCH_QUIET_ACTIVE) and not active_pid:
        return
    if active_pid == str(os.getpid()):
        return
    tmpdir = os.environ.get(config.ENV_DESIGN_TMPDIR, "")
    if not tmpdir or not Path(tmpdir).is_dir():
        tmpdir = os.environ.get(config.ENV_IMPLEMENT_TMPDIR, "")
    if not tmpdir or not Path(tmpdir).is_dir():
        tmpdir = os.environ.get("TMPDIR", "")
    if not tmpdir or not Path(tmpdir).is_dir():
        tmpdir = "/tmp"  # noqa: S108 - lib-quiet parity fallback
    script = Path(argv0 or (sys.argv[0] if sys.argv else "ship.py")).name or "ship.py"
    log_file = os.environ.get(config.ENV_LARCH_QUIET_LOG_FILE, "") or config.PATH_QUIET_LOG_TEMPLATE.format(
        tmpdir=tmpdir,
        script=script,
        pid=os.getpid(),
    )
    try:
        path = Path(log_file)
        path.parent.mkdir(parents=True, exist_ok=True)
        # Python quiet logs intentionally append for crash/retry forensics,
        # unlike bash larch_quiet_init's truncate-per-initialization contract.
        with path.open("a", encoding="utf-8"):
            pass
        _ = os.dup2(1, 3)
        _ = os.dup2(2, 4)
        log_fd = os.open(path, os.O_WRONLY | os.O_APPEND)
        try:
            _ = os.dup2(log_fd, 1)
            _ = os.dup2(log_fd, 2)
        finally:
            os.close(log_fd)
    except OSError:
        _clear_quiet_env()
        _self_initialized_quiet = False
        return
    os.environ[config.ENV_LARCH_QUIET_ACTIVE] = "1"
    os.environ[config.ENV_LARCH_QUIET_PID] = str(os.getpid())
    os.environ[config.ENV_LARCH_QUIET_LOG_FILE] = log_file
    _self_initialized_quiet = True


def contract_stream() -> TextIO:
    """Return the contract stream: fd 3 after quiet init, else stdout."""
    if _self_initialized_quiet or _quiet_active():
        try:
            return os.fdopen(os.dup(3), "w", encoding="utf-8", closefd=True)
        except OSError:
            return sys.stdout
    return sys.stdout


def emit(text: str) -> None:
    """Write a line to the contract stream (fd 3 after quiet_init, else stdout)."""
    stream = contract_stream()
    line = text if text.endswith("\n") else text + "\n"
    _ = stream.write(line)
    stream.flush()


def sanitize_diagnostic_line(text: str) -> str:
    """Strip C0 control bytes and DEL from one diagnostic line (lib-quiet.sh parity)."""
    return "".join(ch for ch in text if ch >= " " and ch != "\x7f")


def sanitize_list(text: str) -> str:
    """Keep only safe characters for comma-separated job KV lists (ci-failed-jobs.sh)."""
    return "".join(ch for ch in text if ch.isalnum() or ch in "_,=:-")


def emit_kv(key: str, value: str) -> None:
    """Write KEY=value to the contract stream. Raises ValueError on embedded newlines."""
    if "\n" in value or "\r" in value:
        raise ValueError(f"emit_kv value for {key!r} contains newline or carriage-return")
    emit(f"{key}={value}")


def diagnostic(message: str) -> None:
    """Write an operator-visible diagnostic after quiet routing may be active."""
    line = redact.redact_outbound(sanitize_diagnostic_line(message)).rstrip("\n") + "\n"
    if _quiet_active():
        if _self_initialized_quiet:
            with suppress(OSError):
                _ = os.write(4, line.encode("utf-8"))
                return
        else:
            log_file = os.environ.get(config.ENV_LARCH_QUIET_LOG_FILE, "")
            if log_file:
                with suppress(OSError):
                    with Path(log_file).open("a", encoding="utf-8") as handle:
                        _ = handle.write(line)
                    return
    _ = sys.stderr.write(line)
    _ = sys.stderr.flush()


@dataclass
class BreadcrumbWriter:
    """Progress breadcrumbs; honor lib-quiet routing when LARCH_QUIET_ACTIVE is set."""

    stream: TextIO | None = None

    def emit(self, message: str, *, quiet: bool | None = None) -> None:
        use_quiet = _quiet_active() if quiet is None else quiet
        line = redact.redact_outbound(message).rstrip("\n") + "\n"
        if use_quiet and not _quiet_disabled():
            routed = False
            log_file = os.environ.get(config.ENV_LARCH_QUIET_LOG_FILE, "")
            if log_file:
                with suppress(OSError):
                    with Path(log_file).open("a", encoding="utf-8") as handle:
                        _ = handle.write(line)
                    routed = True
            if _self_initialized_quiet:  # fd 4 is saved stderr only after quiet_init()
                with suppress(OSError):
                    _ = os.write(4, line.encode("utf-8"))
                    routed = True
            if routed or quiet is True:
                return
        stream = self.stream or sys.stderr
        _ = stream.write(line)
